import "@/components/motion-kit/image-trail-element.ts";

const images = [
  "/images/trail-1.png",
  "/images/trail-2.png",
  "/images/trail-3.png"
];

const config = {
  imageLifespan: 600,
  removalTickMs: 16,
  mouseThreshold: 40,
  minMovementForImage: 5,
  inDuration: 600,
  outDuration: 800,
  maxRotationFactor: 3,
  baseRotation: 30,
  speedSmoothingFactor: 0.25,
  minImageSize: 80,
  maxImageSize: 120,
  staggerOut: 40
};

export default function Page() {
  return (
    <motion-image-trail
      images={images}
      config={config}
      className="w-full h-[600px]"
    />
  );
}
